void put(U64 address, U64 value, std::size_t size = 8) {
    for (std::size_t i = 0; i < size; ++i) memory[address + i] = static_cast<unsigned char>(value >> (8 * i));
}
void putHex(U64 address, const char* hex) {
    const auto digit = [](char c) { return c <= '9' ? c - '0' : c - 'a' + 10; };
    for (std::size_t i = 0; hex[i]; i += 2) put(address + i / 2, static_cast<U64>(16 * digit(hex[i]) + digit(hex[i + 1])), 1);
}
// Ports: no process handles, ReadProcessMemory, module discovery, or Steam calls.
bool readLocal(U64 address, void* target, std::size_t bytes) {
    auto* out = static_cast<unsigned char*>(target);
    for (std::size_t i = 0; i < bytes; ++i) {
        const auto found = memory.find(address + i);
        if (found == memory.end()) return false;
        out[i] = found->second;
    }
    return true;
}
bool identity() { return identityAvailable; }
